		} else {

			setDead();
		}
	}


	private void findFood() {
		Field field = getField();
		Location where = getLocation();
		Object plant = field.getPlantAt(where);

		if (plant instanceof Plant) {
			Plant nearPlant = (Plant) plant;

			if (nearPlant.canEat()) {
				nearPlant.reduceStage();
				setFoodLevel(8);
			}
		}
	}
